head.script:
var credBox;

function closeCredits(el) {
	if (credBox) {
		gui.removeObject(credBox);
		credBox = null;
		return false;
	}
	return true;
}

function showCredits(el) {
	if (credBox) { gui.removeObject(credBox); }
	credBox = gui.createObject("group","textBox",200);
	var text = gui.createObject("text","credText",250,credBox);
	text.text = game.getString(30);
	
	var closeBtn = gui.createObject("button","",250);
	closeBtn.text = game.getString(31);
	closeBtn.setBounds(text.width*0.5 - closeBtn.width*0.5,text.height + 10,-1,-1);
	closeBtn.setAttribute("onclick","closeCredits");
	credBox.addChild(closeBtn);
	credBox.setBounds(0,0,-1,-1);
	credBox.setBounds(512-credBox.width*0.5,384-credBox.height*0.5,-1,-1);
}

function showLibrary(el) {
	game.showLibrary(0);
	return false;
}

function exitGame(el) {
	game.exit();
	return false;
}
